INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IN_ORDER_TO_INCREASE','Како нам је циљ да проширимо нашу дилерску мрежу и проширимо географски домет наше дистрибуције опреме за угоститељство, упућујемо позив компанијама заинтересованим да постану овлашћени дилери за дугорочну сарадњу. Наше партнерство са дилерима нуди атрактивне погодности, укључујући вишестепену структуру попуста, флексибилне опције испоруке и плаћања, свеобухватан пакет транспортних и логистичких услуга, приступ техничким ресурсима и маркетиншки колатерал. Штавише, дилери који активно учествују у владиним тендерским аквизицијама имају право на бонус програме подстицаја који пружају повећане нивое попуста.');
