INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_COUNTRY_TEXT','Земља друге уговорне стране није наведена у рачуноводственом систему.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_COUNTRY_HELP','Нема информација о земљи регистрације вашег налога у нашем систему налога. Обратите се свом менаџеру да додели земљу вашој супротној страни.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_VERIFIED_TEXT','Непотврђена е-пошта.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_VERIFIED_HELP','Још нисте потврдили своју е-пошту. Да бисте потврдили регистрацију, кликните на линк у мејлу који вам је послат након регистрације. Проверите долазне поруке, као и фасциклу Спам. Такође можете поново затражити везу за потврду; молимо идите на страницу:');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_CONFIRMED_DIRECTOR_TEXT','Ваш надзорник је деактивирао налог.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_CONFIRMED_DIRECTOR_HELP','Ваш налог је деактивиран. За више информација обратите се свом надређеном.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_PORTAL_CONFIRMER_TEXT','Налог није потврдио менаџер.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_PORTAL_CONFIRMER_HELP','Ваша регистрација је забележена и наш менаџер је у процесу потврђивања како би вам омогућио потпуни приступ порталу. Сачекајте ову потврду. Ако желите да убрзате процес, можете се обратити директно свом менаџеру.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_ACTIVE_TEXT','Налог је деактивиран.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_ACTIVE_HELP','Ваш налог је деактивиран. За више информација контактирајте свог менаџера.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_ENTITY_TEXT','У нашем рачуноводственом систему није наведено ниједно правно лице.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_ENTITY_HELP','Тренутно немамо информације о вашем правном лицу у нашем рачуноводственом систему. Ако сте нова страна и недавно сте потписали уговор, имајте на уму да може проћи и до једног дана да се ове информације појаве у нашем систему. Ако се обавештење настави након овог временског оквира, контактирајте свог менаџера да реши овај проблем.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_PRICELIST_TEXT','У нашем рачуноводственом систему не постоји ценовник.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_PRICELIST_HELP','У нашем рачуноводственом систему нема информација о условима вашег дилера. Молимо вас да контактирате свог менаџера да бисте добили ценовник додељен вашем налогу.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'YOUR_ACCOUNT_HAS_ERRORS','Постоје грешке на вашем налогу.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'SHOW_MORE','Прикажи више');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'PORTAL_MENU_API','АПИ');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_ACTIVE_DEALER_TEXT','Друга страна је тренутно деактивирана у нашем рачуноводственом систему.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_ACTIVE_DEALER_HELP','Ваш налог друге стране је деактивиран. За више детаља, обратите се свом менаџеру.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_SALES_TYPES_TEXT','У нашем рачуноводственом систему није наведен смер продаје.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_SALES_TYPES_HELP','Смер продаје за ваш налог није наведен у нашем рачуноводственом систему. Контактирајте свог менаџера да додели смер продаје вашој супротној страни.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'DEALERS_API_DOC','Дилерс АПИ документација');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'API_SUPERVISOR_ROLE_REQUIRED','Да бисте генерисали АПИ кључ, морате имати налог са улогом „Надзорник“. Ако ваша компанија тренутно нема такав налог, контактирајте свог менаџера. Алтернативно, ако је потребно само да креирате АПИ кључ за будућу употребу, а ваша компанија већ има налог „Надзорника“, контактирајте власника налога.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'API_API_KEY_WARNING','Генерисањем и коришћењем АПИ кључа потврђујете да сте сагласни са условима коришћења. Сви захтеви направљени помоћу вашег АПИ кључа биће приписани вама. Имајте на уму да ће генерисање новог АПИ кључа деактивирати све претходно креиране кључеве. Биће неопходно ажурирати кључ у свим системима који га користе.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IS_NOT_ENTITY_FOR_PRICES','Наш рачуноводствени систем нема регистровано правно лице. За приступ ценовницима потребно је активно правно лице. Контактирајте свог менаџера да поправи овај проблем.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'LINKS_TO_PRICE_BACKWARD','Везе ка ценовницима са компатибилношћу уназад');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'ATTENTION_DIRECT_LINKS','„Упозорење! Директне везе за преузимање садрже ваш АПИ кључ у нешифрованом облику. Немојте да делите ове везе јавно или ни са ким осим са техничким стручњацима који су укључени у интеграцију каталога. Дељење кључа даје приступ обради трансакција и пошиљака у име вашег правног лица. "');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'IF_FOR_SOME_REASON_NEW_LINKS','Ако нови линкови за преузимање ценовника из било ког разлога нису погодни, можете користити линкове наведене у табели испод. Формат и садржај ових старих ценовника у потпуности су у складу са оним што вам је познато. Међутим, имајте на уму да стари ценовники не нуде могућност избора робе на основу расположивости, искључења ПДВ-а из цене робе, нити узимања у обзир персонализованих услова уговора вашег правног лица. Ако желите да користите ове нове функције, погледајте опције у наставку.');
