INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'PRICE_LITE_RETAIL_CSV_TEXT','<п>Садржи <б>минималне</б> информације о производу, које су доступне у прилагођеном типу описа (вендор.модел). Тип цене - <б>препоручена малопродаја</б>.</п>');
