INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'PRICE_TO_GET_DIRECT_LINK','Морате имати налог са улогом „Супервизор“ да бисте добили директне везе за преузимање ценовника. Ако немате налог са овом улогом, контактирајте свог менаџера. Ако вам је потребно само да добијете директне везе за његово даље коришћење, а ваша компанија има налог „Супервизор“, контактирајте његовог власника.');
