INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'PRICES_D_AVAIL','Доступност: На лагеру. Узима вредности <б>труе</б> ако је производ доступан у наведеном складишту, у супротном <б>фалсе</б>.');
