INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'PRICES_D_PURCHASE_TYPE','Врста куповине. Може да има вредности:<бр/> <ул> <ли><б>"на лагеру"</б> - артикал је на лагеру најмање у једном од изабраних складишта</ли> <ли><б>"на путу"</б> - артикал је у најближој испоруци у складиште у Москви</ли> <ли><б>"на захтев"</б> - роба се може донети у складиште у Москви на захтев. <б>Посебни услови плаћања</б> - проверите код менаџера.</ли> </ул>');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'PRICES_D_DELIVERY_TIME','Време испоруке артикала на захтев у складиште у Москви се мери у данима и може да варира у одређеним вредностима:<бр> <ул> <ли><б>број (дана)</б></ли> <ли> <б>"више није доступно"</б> - испоруке су заустављене,</ли> <ли><б>"провери"</б> - провери код менаџера,</ли> <ли>празан ред - ако рок испоруке није дефинисан</ли> </ул>');
