INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'PRICES_D_TYPEPREFIX','Врста или категорија производа. Узима вредност <б>недефинисано</б> ако није подешено.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'PRICES_D_MODEL','Модел и важни параметри (на пример, индекс модела, карактеристике модификације, итд.). Узима вредност <б>недефинисано</б> ако није подешено.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'PRICES_D_SALES_NOTES','Елемент се користи за приказ информација о:<бр> <ул> <ли>потреби да се код менаџера наведе време испоруке;</ли> <ли>о прекиду куповине артикла (не испоручујемо ставка више).</ли> </ул>');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'PRICES_D_DELIVERY_OPTIONS','Време испоруке <б>за артикле на захтев</б> у складиште у Москви. Вредност се шаље у атрибуту <б>даис</б>. Приказује се само ако је испорука доступна за артикал.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'PRICES_D_WEIGHT','Елемент је дизајниран да одреди тежину предмета. <б>Тежина је у килограмима укључујући паковање</б>.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'PRICES_D_DIMENSIONS','Елемент је дизајниран да одреди димензије артикла (дужина, ширина, висина) у паковању. <б>Димензије су у центиметрима</б>.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'PRICES_D_DELIVERY','Доступност испоруке. Прихвата вредности:<бр> <ул> <ли><б>фалсе</б> — ми више не шаљемо артикал или морате да проверите време испоруке код менаџера;</ли> <ли><б >тачно</б> — ставка може бити испоручена;</ли> </ул>');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'PRICES_D_PICKUP','Доступност за преузимање. Прихвата вредности:<бр> <ул> <ли><б>нетачно</б> — више не испоручујемо артикал и нема га на лагеру;</ли> <ли><б>тачно</б > — артикал је на лагеру или је могућа достава на захтев, можете резервисати изабрани артикал и преузети га сами;</ли> </ул>');
