INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'GROUP_BRANDMANAGER_TEXT','Имате приступ одељку за упите за свој бренд. Конкретно за приватне робне марке, можете управљати каталогом вашег бренда на имек.гкрп.лоцал, потврдити права за преузимање датотека и обавестити главног менаџера о потврдама корисничког портала на вашем сајту. Такође можете погледати цене за све ценовнике, укључујући и оне за ЕУ.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'GROUP_ZIPMANAGER_TEXT','Имате приступ за преглед трансакција и повезаних информација у вези са продајом резервних делова, укључујући све рекламације, као и приступ за преглед свих ценовника.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'GROUP_QUALITYMANAGER_TEXT','Имате приступ свим упитима о трансакцијама, захтевима и жалбама.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'GROUP_SENIORZIPMANAGER_TEXT','У могућности сте да видите трансакције и повезане информације у вези са продајом резервних делова, решавате све рекламације, приступате свим ценовницима, управљате запосленима у свом одељењу, шаљете обавештења главном менаџеру у вези са потврдама корисника на порталу (ако је корисник ваш купац), и региструје трансакције у име другог партнера у смеру продаје резервних делова.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'GROUP_SENIORQUALITYMANAGER_TEXT','Имате приступ свим трансакцијама, жалбама и упитима (додацима) у вези са притужбама. Такође, можете уређивати запослене у свом одељењу.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'GROUP_SENIORCOMPLAINTMANAGER_TEXT','Имате приступ свим трансакцијама, жалбама и упитима (додацима) у вези са притужбама. Такође, можете уређивати запослене у свом одељењу.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'GROUP_COMPLAINTMANAGER_TEXT','Имате приступ захтевима где сте распоређени као главни инжењер.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'GROUP_HEADBRANDMANAGER_TEXT','Имате приступ одељку за упите за свој бренд. Конкретно за приватне робне марке, можете управљати каталогом вашег бренда на имек.гкрп.лоцал, потврдити права за преузимање датотека и обавестити главног менаџера о потврдама корисничког портала на вашем сајту. Такође можете погледати цене за све ценовнике, укључујући и оне за ЕУ.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'GROUP_SENIORBRANDMANAGER_TEXT','Имате приступ одељку за упите за свој бренд. Конкретно за приватне робне марке, можете управљати каталогом вашег бренда на имек.гкрп.лоцал, потврдити права за преузимање датотека и обавестити главног менаџера о потврдама корисничког портала на вашем сајту. Такође можете погледати цене за све ценовнике, укључујући и оне за ЕУ.');
