INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_EXT_ID','Унесите јединствени број артикла производа.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_NAME','Унесите назив производа за приказ у каталогу. Имајте на уму да ако производ већ постоји у каталогу, назив се можда неће појавити. Промена овог поља ће захтевати да производ поново прође модерацију.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_BRAND','Унесите бренд производа. Ако производ већ постоји у каталогу, брендови производа морају се подударати. Промена овог поља ће захтевати да производ поново прође модерацију.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_CATEGORY','Молимо изаберите категорију производа за приказ у каталогу. Ако производ већ постоји у каталогу, категорије производа морају да се подударају. Промена овог поља ће захтевати да производ поново прође модерацију.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_CODE_1C','Попуњује се само ако такав производ већ постоји у каталогу. Ако није, поље мора остати празно.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_PRICE','Унесите цену производа без навођења валуте.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_CURRENCY','Изаберите валуту у којој је наведена цена производа.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_QUANTITY_IN_PACKAGE','Ако се производ продаје у паковању или комплету, унесите количину производа у једном паковању. Ако ово поље остане празно, аутоматски ће се сматрати 1 ставка по пакету.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_FBS','Унесите количину производа коју желите да продате користећи ФБС систем. Оставите ово поље празно ако не желите да продајете производе преко ФБС система.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_DELIVERY_TIME','Унесите број дана који ће бити потребан да роба по наруџбини стигне у ваше складиште. Ово ће укључити време испоруке од вашег складишта до Екуип складишта приликом израчунавања испоруке купцу. Оставите ово поље празно ако не желите да продајете производе по наруџбини.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_DESCRIPTION','Унесите опис производа. Имајте на уму да ако производ већ постоји у каталогу, опис можда неће бити приказан на картици производа. Промена овог поља ће захтевати да производ поново прође модерацију.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_LENGTH','Унесите дужину производа без паковања у милиметрима. Промена овог поља ће захтевати да производ поново прође модерацију.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_HEIGHT','Унесите висину производа без паковања у милиметрима. Промена овог поља ће захтевати да производ поново прође модерацију.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_WIDTH','Унесите ширину производа без паковања у милиметрима. Промена овог поља ће захтевати да производ поново прође модерацију.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_GROSSLENGTH','Унесите дужину производа у пакету у милиметрима. Промена овог поља ће захтевати да производ поново прође модерацију.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_GROSSWIDTH','Унесите ширину производа у пакету у милиметрима. Промена овог поља ће захтевати да производ поново прође модерацију.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_GROSSHEIGHT','Унесите висину производа у пакету у милиметрима. Промена овог поља ће захтевати да производ поново прође модерацију.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_WEIGHT','Унесите тежину производа без паковања у килограмима. Промена овог поља ће захтевати да производ поново прође модерацију.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_POWER','Унесите снагу производа у киловатима. Промена овог поља ће захтевати да производ поново прође модерацију.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_VOLTAGE','Унесите напон производа у волтима. ЦПромена овог поља ће захтевати да производ поново прође модерацију.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_WARRANTY','Унесите гарантни рок за производ у данима. Промена овог поља ће захтевати да производ поново прође модерацију.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'TOOLTIP_COUNTRY','Унесите земљу производње производа. Промена овог поља ће захтевати да производ поново прође модерацију.');
