INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,7,'EXTERNAL_PRODUCT_MODERATION_SUCCESS','Производ добављача је успешно модериран. Да бисте прешли на модерирање следећег производа добављача, кликните на дугме „Следећи производ“. Да бисте затворили прозор за модерирање, кликните на "Откажи"');
